BEGIN READ ONLY;
SET LOCAL statement_timeout = '5s';
SET LOCAL lock_timeout = '1s';
WITH recent AS MATERIALIZED (
  SELECT p.batch_id, p.payload AS plan, r.payload AS result,
    NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p.payload->'candidates') c WHERE c ? 'request') AS all_excluded,
    p.xmin::text AS plan_transaction, r.xmin::text AS result_transaction
  FROM jev_batch_plans p LEFT JOIN jev_batch_results r USING (batch_id)
  WHERE p.authority_generation_hash = (SELECT generation_hash FROM authority_generations ORDER BY activated_at DESC LIMIT 1)
    AND p.payload->>'observedAt' >= '2026-10-18T07:00:00.000Z'
), summary AS (
  SELECT count(*) AS batches, count(*) FILTER (WHERE all_excluded) AS all_excluded_batches,
    count(*) FILTER (WHERE result IS NULL) AS pending_batches,
    count(*) FILTER (WHERE all_excluded AND plan_transaction = result_transaction) AS atomic_excluded_batches,
    min(plan->>'observedAt') AS first_observed_at, max(plan->>'observedAt') AS last_observed_at,
    percentile_cont(0.5) WITHIN GROUP (ORDER BY 1000*extract(epoch FROM ((result->>'completedAt')::timestamptz-(plan->>'observedAt')::timestamptz))) FILTER (WHERE all_excluded AND result IS NOT NULL) AS excluded_batch_p50_ms,
    percentile_cont(0.95) WITHIN GROUP (ORDER BY 1000*extract(epoch FROM ((result->>'completedAt')::timestamptz-(plan->>'observedAt')::timestamptz))) FILTER (WHERE all_excluded AND result IS NOT NULL) AS excluded_batch_p95_ms
  FROM recent
), reasons AS (
 SELECT candidate->>'status' AS status, candidate->'exclusion' AS exclusion, candidate->'reason' AS reason, count(*) AS candidates
 FROM recent CROSS JOIN LATERAL jsonb_array_elements(plan->'candidates') candidate GROUP BY 1,2,3
)
SELECT json_build_object('checkedAt',now(),'scope','latest authority generation since 07:00 UTC','summary',(SELECT row_to_json(summary) FROM summary),'candidates',(SELECT json_agg(reasons) FROM reasons));
COMMIT;
